);}export async function deleteTicket(id:number,signal?:AbortSignal,fetcher:typeof fetch=fetch):Promise<void>{let response:Response;try{response=await fetcher(ticketUrl(id),{method:"DELETE",signal});}catch(error){if(signal?.aborted)throw error;throw new MutationOutcomeError();}if(response.status===404)return;if(!response.ok)throw await httpError(response);if(response.status!==204)throw new MutationOutcomeError();}

